state.mt76_attach:
int mt76_npu_init(struct mt76_dev *dev, phys_addr_t phy_addr, u64 bar_bytes, int type)
{
	struct airoha_ppe_dev *ppe_dev;
	struct airoha_npu *npu;
	int err = 0;

	mutex_lock(&dev->mutex);

	npu = airoha_npu_get(dev->dev);
	if (IS_ERR(npu)) {
		request_module("airoha-npu");
		npu = airoha_npu_get(dev->dev);
	}

	if (IS_ERR(npu)) {
		err = PTR_ERR(npu);
		goto error_unlock;
	}

	ppe_dev = airoha_ppe_get_dev(dev->dev);
	if (IS_ERR(ppe_dev)) {
		request_module("airoha-eth");
		ppe_dev = airoha_ppe_get_dev(dev->dev);
	}

	if (IS_ERR(ppe_dev)) {
		err = PTR_ERR(ppe_dev);
		goto error_npu_put;
	}

	err = airoha_npu_wlan_init_reserved_memory(npu);
	if (err)
		goto error_ppe_put;
	err = airoha_npu_wlan_bind_endpoint(npu, phy_addr, bar_bytes, type);
	if (err)
		goto error_ppe_put;

	dev->dma_dev = npu->dev;
	dev->mmio.phy_addr = phy_addr;
	dev->mmio.npu_type = type;
	/* NPU offloading requires HW-RRO for RX packet reordering. */
	dev->hwrro_mode = is_mt7996(dev) ? MT76_HWRRO_V3 : MT76_HWRRO_V3_1;
	dev->rx_token_size = 32768;

	rcu_assign_pointer(dev->mmio.npu, npu);
	rcu_assign_pointer(dev->mmio.ppe_dev, ppe_dev);
	synchronize_rcu();

	mutex_unlock(&dev->mutex);

	return 0;

error_ppe_put:
	airoha_ppe_put_dev(ppe_dev);
error_npu_put:
	airoha_npu_put(npu);
error_unlock:
	mutex_unlock(&dev->mutex);

	return err;
}

state.tx_allocate:
int mt7996_npu_hw_init(struct mt7996_dev *dev)
{
	int i, err;

	if (!mt76_npu_device_active(&dev->mt76))
		return 0;

	BUILD_BUG_ON(ARRAY_SIZE(dev->npu_txd_addr) % 3);

	for (i = 0; i < ARRAY_SIZE(dev->npu_txd_addr); i += 3) {
		int band = i && is_mt7996(&dev->mt76) ? MT_BAND2 : MT_BAND0;
		u32 size = is_mt7996(&dev->mt76) ? band == MT_BAND2
						 ? MT7996_NPU_TX_RING_SIZE
						 : MT7996_NPU_RX_RING_SIZE / 2
						 : MT7996_TX_RING_SIZE;

		if (!dmam_alloc_coherent(dev->mt76.dma_dev, 256 * size,
					 &dev->npu_txd_addr[i], GFP_KERNEL))
			return -ENOMEM;

		if (!dmam_alloc_coherent(dev->mt76.dma_dev, 256 * size,
					 &dev->npu_txd_addr[i + 1],
					 GFP_KERNEL))
			return -ENOMEM;

		if (!dmam_alloc_coherent(dev->mt76.dma_dev, 256 * 1024,
					 &dev->npu_txd_addr[i + 2],
					 GFP_KERNEL))
			return -ENOMEM;
	}

	mutex_lock(&dev->mt76.mutex);
	err = __mt7996_npu_hw_init(dev);
	mutex_unlock(&dev->mt76.mutex);

	return err;
}

state.provider_cleanup:
static void airoha_npu_dma_cleanup(void *data)
{
	struct airoha_npu_dma_lifetime *life = data;
	unsigned int i;

	/* No physical retirement witness exists yet. Publication errors, detach
	 * and software parking must not release possibly device-owned mailboxes.
	 */
	if (life->exposed) {
		mutex_lock(&airoha_npu_retained_lock);
		list_add_tail(&life->retained, &airoha_npu_retained_dma);
		mutex_unlock(&airoha_npu_retained_lock);
		dev_warn(life->dev, "retaining NPU DMA mailboxes pending retirement proof\n");
		return;
	}
	for (i = 0; i < ARRAY_SIZE(life->buffers); i++)
		if (life->buffers[i].buf)
			dma_free_coherent(life->dev, AIROHA_NPU_MBOX_SIZE,
					  life->buffers[i].buf, life->buffers[i].addr);
	put_device(life->dev);
	kfree(life);
}

state.provider_lifetime:
struct airoha_npu_dma_lifetime {
	struct device *dev;
	struct list_head retained;
	struct {
		void *buf;
		dma_addr_t addr;
	} buffers[NPU_NUM_CORES];
	bool exposed;
};
